import React from "react";
import {Card, type PiCardProps} from "@pihanga2/core";

import {Button, LinkButton} from "@/components/ui/button";
import {Tooltip, TooltipContent, TooltipTrigger} from "@/components/ui/tooltip";
import {getIcon} from "@/cards/icons";
import {useDropdownOpen} from "@/cards/dropDownMenu/dropdown-context";

import type {PiButtonEvents, PiButtonProps} from "./button.types";

function resolveIconByName(name?: string): React.ReactNode {
  if (!name) return null;
  return getIcon(name);
}

export const ButtonComponent = (
  props: PiCardProps<PiButtonProps, PiButtonEvents>,
): React.ReactNode => {
  const {
    opts,
    ariaLabel,
    label,
    iconLabel,
    contentCard: content,
    href,
    target,
    tooltip,
    tooltipCard,
    tooltipMode,
    tooltipPlacement,
    className,
    id,
    onClicked,
    cardName,
    _cls,
    active,
    focused,
    disabled,
    loading,
    isPending,
  } = props;

  // Check if this button is inside an open dropdown menu
  const isInsideOpenDropdown = useDropdownOpen();

  const beforeIcon = resolveIconByName(opts?.beforeIcon);
  const afterIcon = resolveIconByName(opts?.afterIcon);

  // Determine base content: iconLabel takes precedence, then contentCard, then label
  const baseContent = iconLabel ? (
    resolveIconByName(iconLabel)
  ) : content ? (
    <Card cardName={content} parentCard={cardName} />
  ) : (
    label
  );

  // Render icons as children following shadcn/ui pattern
  const children = (
    <>
      {beforeIcon}
      {baseContent}
      {afterIcon}
    </>
  );

  const common = {
    active,
    focused,
    isMenu: opts?.isMenu,
    truncate: opts?.truncate,
    variant: opts?.variant,
    size: opts?.size,

    disabled,
    loading,
    isPending,
    loadingClassName: opts?.loadingClassName,

    className: `${_cls("root")} ${className || ""}`.trim(),
  };

  const handleClick = () => {
    onClicked({id});
  };

  const renderButton = () => {
    if (href) {
      return (
        <LinkButton
          {...common}
          href={href}
          target={target}
          data-pihanga={cardName}
          label={ariaLabel ?? label}
          onClick={handleClick}
        >
          {children}
        </LinkButton>
      );
    }

    return (
      <Button
        {...common}
        data-pihanga={cardName}
        label={ariaLabel ?? label}
        onClick={handleClick}
      >
        {children}
      </Button>
    );
  };

  if (!tooltip && !tooltipCard) return renderButton();

  // Determine tooltip open state based on mode.
  // If the button is inside an open dropdown, force the tooltip closed
  // to avoid UI conflicts (dropdown menu should take precedence).
  const tooltipOpen = isInsideOpenDropdown
    ? false
    : tooltipMode === "open"
      ? true
      : tooltipMode === "closed"
        ? false
        : undefined; // 'auto' or undefined = uncontrolled

  // Render tooltip content: use tooltipCard if provided, otherwise use tooltip string
  const tooltipContent = tooltipCard ? (
    <Card cardName={tooltipCard} parentCard={cardName} />
  ) : (
    <p data-pihanga={`${cardName}-tooltip`}>{tooltip}</p>
  );

  return (
    <Tooltip open={tooltipOpen}>
      <TooltipTrigger asChild>{renderButton()}</TooltipTrigger>
      <TooltipContent side={tooltipPlacement}>{tooltipContent}</TooltipContent>
    </Tooltip>
  );
};

import {
  createCardDeclaration,
  createOnAction,
  PiCardRef,
  registerActions,
} from "@pihanga2/core";

export const PI_BUTTON_CARD = "pi/button";

export const Button = createCardDeclaration<PiButtonProps, PiButtonEvents>(
  PI_BUTTON_CARD,
);

export const PI_BUTTON_ACTION = registerActions(PI_BUTTON_CARD, ["clicked"]);

export const onButtonClicked = createOnAction<PiButtonClickedEvent>(
  PI_BUTTON_ACTION.CLICKED,
);

/* @deprecated Use `onButtonClicked` instead. */
export const onPiButtonClicked = onButtonClicked;

/**
 * Declarative "opts" subset based on `src/registry/ui/button.tsx`.
 *
 * Notes:
 * - Any icon is referenced by name and resolved via `src/pihanga/icons.ts`.
 * - `children` are provided via `label` (simple) or `content` (card ref).
 */
export type PiButtonOpts = {
  /**
   * Visual style variant of the button.
   * Determines the button's appearance (colors, borders, etc.).
   */
  variant?:
    | "default"
    | "destructive"
    | "outline"
    | "secondary"
    | "ghost"
    | "ghost2"
    | "ghost3"
    | "ghostActive"
    | "brand"
    | "nav"
    | "navAction"
    | "menuAction"
    | "blockAction"
    | "blockActionSecondary"
    | "primaryOutline"
    | "radio"
    | "none";

  /**
   * Size of the button.
   * Controls padding, font size, and overall dimensions.
   */
  size?:
    | "default"
    | "xs"
    | "sm"
    | "md"
    | "lg"
    | "icon"
    | "iconSm"
    | "navAction"
    | "menuAction"
    | "blockAction"
    | "none";

  /** Truncate button content with ellipsis if it overflows. */
  truncate?: boolean;

  /** If true, button is rendered as a menu trigger button. */
  isMenu?: boolean;

  /** Custom CSS class to apply to the loading spinner/indicator. */
  loadingClassName?: string;

  /** Icon to display before the button content. Set 'size' to 'icon' if ONLY show icon */
  beforeIcon?: string;

  /** Icon to display after the button content */
  afterIcon?: string;
};

export type PiButtonProps = {
  id?: string; // optional 'id' to be added to events

  /**
   * Optional explicit aria-label.
   *
   * Useful for icon-only / letter-only buttons where the visible content
   * shouldn't be used as the accessible name.
   */
  ariaLabel?: string;

  /**
   * Declarative options; maps closely to `@/components/ui/button`.
   */
  opts?: PiButtonOpts;

  /** Simple label; used as children and aria-label fallback. */
  label?: string;

  /**
   * Icon name to use as the main button content (instead of text label).
   * Resolved via `src/pihanga/icons.ts`.
   * Takes precedence over `label` and `contentCard`.
   */
  iconLabel?: string;

  /**
   * If set, renders this card as the content instead of `label`.
   * (Useful for rich content.)
   */
  contentCard?: PiCardRef;

  /** When provided, button will render as an anchor. */
  href?: string;
  target?: string;

  tooltip?: string;

  /**
   * If set, renders this card as the tooltip content instead of `tooltip`.
   * (Useful for rich tooltip content.)
   */
  tooltipCard?: PiCardRef;

  /**
   * Controls tooltip visibility mode.
   * - 'auto' (default): Normal hover behavior
   * - 'open': Force tooltip to be visible
   * - 'closed': Force tooltip to be hidden
   */
  tooltipMode?: "auto" | "open" | "closed";

  /**
   * Controls tooltip placement/position.
   * - 'top': Tooltip appears above the button (default)
   * - 'right': Tooltip appears to the right of the button
   * - 'bottom': Tooltip appears below the button
   * - 'left': Tooltip appears to the left of the button
   */
  tooltipPlacement?: "top" | "right" | "bottom" | "left";

  /** Indicates whether the button is in an active/selected state. */
  active?: boolean;

  /** Indicates whether the button has focus state styling applied. */
  focused?: boolean;

  /** If true, disables the button and prevents interaction. */
  disabled?: boolean;

  /** If true, shows loading state and typically disables interaction. */
  loading?: boolean;

  /** If true, indicates an async operation is pending (similar to loading but distinct). */
  isPending?: boolean;

  className?: string;
};

export type PiButtonClickedEvent = {
  id?: string;
};

export type PiButtonEvents = {
  onClicked: PiButtonClickedEvent;
};

import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {ButtonComponent} from "./button.component";
import {PI_BUTTON_ACTION, PI_BUTTON_CARD} from "./button.types";

export * from "./button.types";

// Optional convenience alias (mirrors older pattern like SdDropDownMenu)
// export const SdButton = createCardDeclaration<PiButtonProps, PiButtonEvents>(
//   PI_BUTTON_CARD,
// );

registerCardComponent({
  name: PI_BUTTON_CARD,
  component: ButtonComponent,
  events: actionTypesToEvents(PI_BUTTON_ACTION),
});
